<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ResearchConsentConnectorFixture.php';
use DigiForge\Database\Tables;
use DigiForge\Portal\ResearchRunWorkflow;
/** Selected connector/credential generation is current consent evidence, never provider authority. */
final class ResearchConsentConnectorGenerationTest extends WP_UnitTestCase
{
 private ResearchConsentConnectorFixture $fixture;private Closure $denySecret;private int $secretReads=0;
 protected function setUp():void {parent::setUp();$this->fixture=new ResearchConsentConnectorFixture();$this->fixture->boot();$this->denySecret=function(string $sql):string {if(str_starts_with(ltrim($sql),'SELECT')&&str_contains($sql,Tables::integration_secrets())&&preg_match('/\b(?:ciphertext|\*)\b/i',$sql)){++$this->secretReads;return 'SELECT NULL AS ciphertext WHERE 1=0';}return $sql;};add_filter('query',$this->denySecret,PHP_INT_MAX);}
 protected function tearDown():void {try{remove_filter('query',$this->denySecret,PHP_INT_MAX);$this->fixture->restore();self::assertSame(0,$this->secretReads,'Metadata-only consent checks must never select/decrypt ciphertext.');}finally{parent::tearDown();}}
 public function testCredentialRotationInvalidatesNativeConsentBeforeConsumption():void {$prepared=$this->fixture->prepare();global $wpdb;$wpdb->update(Tables::integration_secrets(),['fingerprint'=>'fedcba0987654321'],['integration_id'=>$prepared['connector'],'secret_name'=>'api_key']);$denied=$this->fixture->call('invoke',ResearchRunWorkflow::EXECUTE_ACTION,$prepared['body']+['df_confirm_research_run'=>'1'],true);self::assertStringContainsString('stale',$denied['df_message']);$this->fixture->assertNotConsumed($prepared);}
 public function testSelectedConnectorReplacementRemovesConfirmationForm():void {$prepared=$this->fixture->prepare();$this->fixture->connector();$html=$this->fixture->call('render','personalized_pod',['df_research_run'=>$prepared['operation']]);self::assertStringNotContainsString('name="df_research_signature"',$html);self::assertStringContainsString('stale',$html);$this->fixture->assertNotConsumed($prepared);}
 public function testUnchangedSelectedGenerationKeepsConfirmationAndIgnoresUnselectedConnector():void {$prepared=$this->fixture->prepare();global $wpdb;$wpdb->insert(Tables::integrations(),['provider'=>'ai','environment'=>'production','connection_key'=>'disabled-synthetic-'.wp_generate_uuid4(),'display_name'=>'UNSELECTED','status'=>'CONFIGURED','enabled'=>0,'config'=>'{}','created_at'=>gmdate('Y-m-d H:i:s'),'updated_at'=>gmdate('Y-m-d H:i:s')]);$html=$this->fixture->call('render','personalized_pod',['df_research_run'=>$prepared['operation']]);self::assertStringContainsString('name="df_research_signature"',$html);$this->fixture->assertNotConsumed($prepared);}
 public function testMetadataReadFailureHidesConfirmationWithoutConsumption():void {$prepared=$this->fixture->prepare();global $wpdb;$fault=static fn(string $sql):string=>str_starts_with(ltrim($sql),'SELECT')&&str_contains($sql,Tables::integration_secrets())?'SELECT * FROM synthetic_missing_consent_metadata':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$fault,99);try{$html=$this->fixture->call('render','personalized_pod',['df_research_run'=>$prepared['operation']]);self::assertStringNotContainsString('name="df_research_signature"',$html);$this->fixture->assertNotConsumed($prepared);}finally{remove_filter('query',$fault,99);$wpdb->suppress_errors($prior);}}
}
